    {selected && !viewOnly && !styleOpen && (() => { const shape = elements.find(e => e.id === selected); if (!shape) return null; const update = (patch: Partial<Shape>) => {if(shape.locked&&!('locked'in patch)){setStatus('Unlock the element before editing');return;} commit(elements); const geometry=Object.keys(patch).some(key=>['x','y','width','height','rotation'].includes(key));const moved=geometry?applyGeometryFields(elements,new Set([selected]),patch):elements; const multiple = Object.keys(patch).every(key=>['color','fill','strokeWidth','opacity','locked','hidden','iconMode'].includes(key)); setElements(refreshBindings(elements,moved.map(e => (multiple ? selection.includes(e.id) : e.id === selected) ? componentOverrides(e,growText({ ...e, ...patch })) : e))); }; return <section className="properties" aria-label="Element properties"><strong>{shape.type}</strong><label>Text<input value={shape.text || ''} onChange={e => update({ text: e.target.value })}/></label>{(['x', 'y', 'width', 'height', 'rotation'] as const).map(key => <label key={key}>{key}<input type="number" value={shape[key]} onChange={e => { const value = e.target.valueAsNumber; if (Number.isFinite(value)) update({ [key]: value }); }}/></label>)}{shape.type === 'icon' && <label>Icon style<select value={shape.iconMode || 'handdrawn'} onChange={e=>update({iconMode:e.target.value as IconMode})}><option value="handdrawn">Hand drawn</option><option value="monochrome">Monochrome</option><option value="original">Original colours</option></select></label>}<label>Link drawing<select value={shape.link?.drawingId||''} onChange={e=>update({link:e.target.value?{drawingId:e.target.value}:undefined})}><option value="">None</option>{workspace.entries.filter(e=>e.kind==='drawing'&&!isTrashed(workspace,e)).map(e=><option key={e.id} value={e.id}>{e.title}</option>)}</select></label>{shape.link&&<label>Link target<select value={shape.link.elementId||''} onChange={e=>update({link:{drawingId:shape.link!.drawingId,elementId:e.target.value||undefined}})}><option value="">Whole drawing</option>{(workspace.drawings[shape.link.drawingId]?.elements||[]).map(e=><option key={e.id} value={e.id}>{e.text||e.type} · {e.id.slice(0,6)}</option>)}</select></label>}{shape.type==='pen'&&<label>Smoothing<input type="range" min="0" max="1" step=".05" value={shape.smoothing??.5} onChange={e=>update({smoothing:e.target.valueAsNumber})}/></label>}{(shape.type==='arrow'||shape.type==='line')&&<label>Route<select value={shape.arrowStyle||'straight'} onChange={e=>update({arrowStyle:e.target.value as Shape['arrowStyle'],points:e.target.value==='straight'?[connectorPoints(shape)[0]!,connectorPoints(shape).at(-1)!]:shape.points})}><option value="straight">Straight</option><option value="curved">Curved</option><option value="elbow">Elbow (avoids shapes)</option></select></label>}{shape.type==='arrow'&&(['start','end']as const).map(side=><label key={side}>{side} head<select value={(side==='start'?shape.startArrowhead:shape.endArrowhead)||(side==='start'?'none':'arrow')} onChange={e=>update({[side==='start'?'startArrowhead':'endArrowhead']:e.target.value})}>{arrowheads.map(head=><option key={head}>{head}</option>)}</select></label>)}<label>Stroke<input type="color" value={shape.color || '#292929'} onChange={e => update({ color: e.target.value })}/></label><label>Fill<input type="color" value={shape.fill || '#ffffff'} onChange={e => update({ fill: e.target.value })}/></label><button onClick={() => update({ fill: undefined })}>No fill</button><label>Width<input type="number" min="0" max="100" value={shape.strokeWidth ?? 1.8} onChange={e => { const value = e.target.valueAsNumber; if (Number.isFinite(value) && value >= 0 && value <= 100) update({ strokeWidth: value }); }}/></label><label>Opacity<input type="range" min="0" max="1" step="0.05" value={shape.opacity ?? 1} onChange={e => update({ opacity: e.target.valueAsNumber })}/></label><button onClick={() => { update({ locked: !shape.locked }); setSelected(null); }}>{shape.locked?'Unlock':'Lock'}</button><button onClick={() => { update({ hidden: true }); setSelected(null); }}>Hide</button><button onClick={()=>actions.search().find(action=>action.id==='layer-front')?.run()}>Bring to front</button></section>; })()}
    {styleOpen&&selected&&!viewOnly&&(()=>{const element=elements.find(e=>e.id===selected);return element?<StylePanel element={element} apply={applyStyle} styles={workspace.styles||[]} close={()=>{setStyleOpen(false);canvas.current?.focus();}} save={(name,style)=>{if((workspace.styles?.length||0)>=200){setStatus('Named styles are limited to 200');return;}setWorkspace({...stash(),styles:[...(workspace.styles||[]),{id:crypto.randomUUID(),name,style}]});}} remove={id=>setWorkspace({...stash(),styles:workspace.styles?.filter(style=>style.id!==id)})}/>:null;})()}
    {componentsOpen&&<ComponentPanel definitions={workspace.components||[]} close={()=>{setComponentsOpen(false);canvas.current?.focus();}} insert={id=>{if(viewOnly)return;const definition=workspace.components?.find(c=>c.id===id);if(!definition)return;const items=instantiateComponent(definition,(innerWidth/2-view.x)/view.zoom,(innerHeight/2-view.y)/view.zoom);commit(elements);setElements([...elements,...items]);setSelection(items.map(e=>e.id));}} update={id=>{if(viewOnly)return;try{const saved=stash(),captured=createComponent(saved,saved.currentId,selection,'Source'),components=saved.components?.map(c=>c.id===id?{...c,drawingId:saved.currentId,sourceIds:captured.sourceIds}:c),synced=syncComponents({...saved,components});workspaceRef.current=synced;setWorkspace(synced);commit(elements);setElements(synced.drawings[synced.currentId]!.elements);}catch(error){setStatus(String(error));}}} detach={()=>{if(viewOnly)return;const ids=new Set(selectionClosure(elements,selection));commit(elements);setElements(elements.map(e=>ids.has(e.id)?{...e,component:undefined}:e));}} remove={id=>{if(viewOnly)return;const saved=stash();setWorkspace({...saved,components:saved.components?.filter(c=>c.id!==id),drawings:Object.fromEntries(Object.entries(saved.drawings).map(([key,d])=>[key,{...d,elements:d.elements.map(e=>e.component?.definitionId===id?{...e,component:undefined}:e)}]))});commit(elements);setElements(elements.map(e=>e.component?.definitionId===id?{...e,component:undefined}:e));}}/>}
    {peers.filter(p=>p.cursor).map(p=><div key={p.peer} className="peer-cursor" aria-hidden="true" style={{left:p.cursor!.x*view.zoom+view.x,top:p.cursor!.y*view.zoom+view.y,borderColor:p.color}}><span style={{background:p.color}}>{p.name}</span></div>)}
    {!zen&&threads.filter(t=>!t.resolved).map(t=>{const target=t.elementId?elements.find(e=>e.id===t.elementId):undefined,x=target?target.x+target.width:t.x,y=target?target.y:t.y;return <button key={t.id} className="comment-pin" style={{left:x*view.zoom+view.x,top:y*view.zoom+view.y}} aria-label={`Comment thread: ${t.comments[0]?.text}`} onClick={()=>setCommentsOpen(true)}>{t.comments.length}</button>;})}
    {shareOpen&&collabEnabled&&<SharePanel user={user} setUser={setUser} share={share} role={collabRole} start={startShare} rotate={rotateShare} stop={leaveShare} known={knownShares} openShared={openShared} teamLibrary={teamLibrary} close={()=>{setShareOpen(false);canvas.current?.focus();}}/>}
    {commentsOpen&&<CommentsPanel threads={threads} me={me} canComment={!collab.current||collab.current.canComment()} seen={ids=>setSeenMentions(list=>[...new Set([...list,...ids])])} reply={(threadId,text)=>commentEvent({kind:'reply',threadId,comment:{id:crypto.randomUUID(),author:me,text,time:Date.now()}})} resolve={(threadId,resolved)=>commentEvent({kind:'resolve',threadId,resolved})} jump={t=>{const target=t.elementId?elements.find(e=>e.id===t.elementId):undefined;const x=target?target.x+target.width/2:t.x,y=target?target.y+target.height/2:t.y;setView(v=>({...v,x:innerWidth/2-x*v.zoom,y:innerHeight/2-y*v.zoom}));if(target)setSelected(target.id);}} close={()=>{setCommentsOpen(false);canvas.current?.focus();}}/>}
    {viewOnly && <div className="mode-label">{collabRole==='commenter'?'Comment only':'View only'}</div>}
    {numericInput!==null&&<form className="numeric-command" onSubmit={e=>{e.preventDefault();try{const fields=parseNumericCommand(numericInput);commit(elements);setElements(applyGeometryFields(elements,new Set(selection),fields));setNumericInput(null);canvas.current?.focus();}catch(error){setNumericError(String(error));}}}><label>Set geometry<input autoFocus aria-label="Numeric geometry command" value={numericInput} onChange={e=>setNumericInput(e.target.value)} onKeyDown={e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();setNumericInput(null);canvas.current?.focus();}}}/></label><button>Apply</button><button type="button" onClick={()=>{setNumericInput(null);canvas.current?.focus();}}>Cancel</button>{numericError&&<p role="alert">{numericError}</p>}</form>}
    {editingId&&!viewOnly&&elements.some(e=>e.id===editingId&&!e.locked)&&<RichEditor drawings={workspace.entries.filter(e=>e.kind==='drawing'&&!isTrashed(workspace,e)&&e.id!==workspace.currentId).map(e=>({id:e.id,title:e.title}))} findIcon={(element,token)=>{inlineIcon.current={elementId:element.id,token,source:element.text||''};iconPosition.current={x:element.x+12,y:element.y+12};setIconQuery(token.query);setIconsOpen(true);}} element={elements.find(e=>e.id===editingId)!} close={()=>{setEditingId(null);canvas.current?.focus();}} update={element=>{commit(elements);setElements(refreshBindings(elements,elements.map(e=>e.id===element.id?componentOverrides(e,growText(element)):e)));}}/>}
    {linksOpen&&<section className="code-panel" aria-label="Drawing backlinks"><div className="workspace-heading"><strong>Backlinks</strong><button onClick={()=>setLinksOpen(false)} aria-label="Close backlinks">×</button></div><div className="snapshot-list">{backlinks(stash(),workspace.currentId).map(({entry,element})=><div key={entry.id+element.id}><button onClick={()=>openDrawing(entry.id,element.id)}>{entry.title} · {element.text||element.type}</button></div>)}</div><p>Select an element and use its properties to link it to a drawing, frame, or element.</p></section>}
    {settingsOpen&&<CanvasSettings settings={settings} change={value=>{const saved=stash();saved.drawings[saved.currentId]!.settings=value;setWorkspace(saved);}} theme={contrast?'contrast':dark?'dark':'light'} setTheme={value=>{setDark(value==='dark');setContrast(value==='contrast');}} close={()=>setSettingsOpen(false)}/>}
    {minimap&&!presenting&&<Minimap elements={elements} view={view} navigate={(x,y)=>setView(v=>({...v,x:innerWidth/2-x*v.zoom,y:innerHeight/2-y*v.zoom}))}/>}
    {iconsOpen && <Suspense fallback={<div className="mode-label">Opening icons…</div>}><IconPanel initialQuery={iconQuery} insertScene={items=>{if(viewOnly||!loaded)return;const copies=cloneSelection(items,items.map(e=>e.id),(innerWidth/2-view.x)/view.zoom,(innerHeight/2-view.y)/view.zoom);commit(elements);setElements([...elements,...copies]);setSelection(copies.map(e=>e.id));setIconsOpen(false);}} close={() => {inlineIcon.current=null;setIconsOpen(false);canvas.current?.focus();}} insert={(icon:IconArtwork,mode:IconMode)=>insertIcon(icon,mode)}/></Suspense>}
    {excalidrawOpen&&<ExcalidrawPanel elements={elements} close={()=>{setExcalidrawOpen(false);canvas.current?.focus();}}/>}
    {exportOpen && <ExportPanel clean={!!settings.clean} elements={elements} selected={selected} selectedIds={selection} dark={dark} close={() => {setExportOpen(false);canvas.current?.focus();}}/>}
    {keymapOpen && <KeymapPanel actions={actions.search()} keymap={keymap} update={setKeymap} close={() => {setKeymapOpen(false);canvas.current?.focus();}}/>}
    {slidesOpen && !presenting && <PresentationPanel clean={!!settings.clean} frames={slides} elements={elements} dark={dark} readOnly={viewOnly} close={() => {setSlidesOpen(false);canvas.current?.focus();}} change={frames => { commit(elements); const ids = new Set(frames.map(e => e.id)); setElements([...elements.filter(e => !ids.has(e.id)), ...frames]); }} navigate={frame => setView(frameViewport(frame, innerWidth, innerHeight))}/>}
    {presenting && <div className="presentation-controls"><button onClick={() => setSlideIndex(i => Math.max(0, i - 1))}>Previous</button><span>{slideIndex + 1} / {slides.length}</span><button onClick={() => setSlideIndex(i => Math.min(slides.length - 1, i + 1))}>Next</button><button aria-pressed={presentPen} onClick={()=>setPresentPen(v=>!v)}>{presentPen?'Pen on · P':'Laser · K / Pen · P'}</button><button onClick={() => setPresenting(false)}>Exit · Esc</button></div>}
