    {codePanel && <section className="code-panel" aria-label="Diagram as code"><div className="workspace-heading"><strong>Diagram as code · {(()=>{const l=detectLanguage(diagramCode);return l==='d2'?'D2':l==='dsl'?'Native DSL':`Mermaid ${l}`;})()}</strong><button onClick={() => {setCodePanel(false);canvas.current?.focus();}} aria-label="Close code panel">×</button></div><p>Mermaid (flowchart, sequence, class, state, ER, gantt, mind map), D2, or the native DSL. Code edits update the canvas; label, node and edge edits on the canvas update the code. Manual styles survive regeneration.</p><textarea aria-label="Diagram source" value={diagramCode} onChange={e => {const value=e.target.value;setDiagramCode(value);if(autoSync){if(codeTimer.current)clearTimeout(codeTimer.current);codeTimer.current=setTimeout(()=>applyCode(value),500);}}} spellCheck={false}/><div className="code-actions"><label><input type="checkbox" checked={autoSync} onChange={e=>setAutoSync(e.target.checked)}/> Sync both ways</label><button disabled={viewOnly} onClick={() => applyCode(diagramCode)}>Apply to canvas</button><button onClick={() => { try { setDiagramCode(elementsToMermaid(elements.filter(e=>!['text','frame','pen','image','icon'].includes(e.type)))); setCodeError(''); } catch (error) { setCodeError(String(error)); } }}>Replace with Mermaid from canvas</button></div>{codeError && <p role="alert">{codeError}</p>}</section>}
    {templates && <div className="overlay" onMouseDown={() => setTemplates(false)}><section className="palette template-panel" role="dialog" aria-label="Templates" onMouseDown={e => e.stopPropagation()}><div className="workspace-heading"><strong>Start with a template</strong><button onClick={() => {setTemplates(false);canvas.current?.focus();}} aria-label="Close templates">×</button></div>{[...starterTemplates,...workspace.entries.filter(e=>e.template&&!isTrashed(workspace,e)).map(e=>({title:e.title,create:()=>{const items=workspace.drawings[e.id]!.elements;return cloneSelection(items,items.map(e=>e.id),0,0);}}))].map((template,index) => <button key={template.title+index} disabled={viewOnly || !loaded} onClick={() => { const saved = stash(); const entry = createEntry('drawing', template.title); saved.entries.push(entry); const drawing = { ...emptyDrawing(), elements: template.create() }; saved.drawings[entry.id] = drawing; saved.currentId = entry.id; history.current = drawing.history; pendingHistory.current = null; loadElements(drawing.elements); setWorkspace(saved); setSelected(null); setTemplates(false); }}>{template.title}<span>↗</span></button>)}</section></div>}
